radar-beta
    axis A,B,C
    curve mycurve{1,2,3}

radar-beta
    axis A,B,C
    curve mycurve{ C: 3, A: 1, B: 2 }

radar-beta
        axis A,B,C
        curve mycurve{1,2,3}

radar-beta
      axis ax1, ax2
      curve my-curve { 1, ax1 2 }

radar-beta
      axis ax1, ax2
      curve my-curve { ax1 1 ax2 2 }

radar-beta
  title Frontend Framework Comparison
  axis perf["Performance"], dx["Dev Experience"], eco["Ecosystem"]
  axis learn["Easy to Learn"], docs["Documentation"]

  curve react["React"]{4, 4, 5, 3, 4}
  curve vue["Vue"]{4, 5, 4, 4, 5}
  curve svelte["Svelte"]{5, 5, 3, 4, 4}

  graticule polygon
  max 5
  min 0

radar-beta
  title Restaurant Comparison
  axis food["Food Quality"], service["Service"], price["Price"]
  axis ambiance["Ambiance"]

  curve a["Restaurant A"]{4, 3, 2, 4}
  curve b["Restaurant B"]{3, 4, 3, 3}
  curve c["Restaurant C"]{2, 3, 4, 2}
  curve d["Restaurant D"]{2, 2, 4, 3}

  graticule polygon
  max 5
